SELECT c.id AS chunk_id, c.doc_id AS doc_id, c.kb_id AS kb_id, c.text AS text, c.ordinal AS ordinal, COALESCE(d.title, '') AS title, (c.embedding_vec <=> CAST(#{vectorLiteral} AS vector)) AS distance FROM kb_chunk c JOIN kb_base b ON b.id = c.kb_id AND b.deleted = FALSE LEFT JOIN kb_document d ON d.id = c.doc_id AND d.deleted = FALSE WHERE c.deleted = FALSE AND c.embedding_vec IS NOT NULL AND c.workspace_id = #{workspaceId}
AND c.kb_id IN
#{kid}
AND (
${vfSql} TRUE
)
ORDER BY c.embedding_vec <=> CAST(#{vectorLiteral} AS vector) LIMIT #{k}
